import{_ as t,c as a,o as i,aj as l}from"./chunks/framework.CDhdelVI.js";const u=JSON.parse('{"title":"No-knead Tortillas","description":"Soft, flexible no-knead tortillas made with boiling water for maximum pliability. Ready in about 90 minutes.","frontmatter":{"title":"No-knead Tortillas","description":"Soft, flexible no-knead tortillas made with boiling water for maximum pliability. Ready in about 90 minutes.","head":[["meta",{"name":"description","content":"Soft, flexible no-knead tortillas made with boiling water for maximum pliability. Ready in about 90 minutes."}],["meta",{"property":"og:title","content":"No-knead Tortillas"}],["meta",{"property":"og:description","content":"Soft, flexible no-knead tortillas made with boiling water for maximum pliability."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/recipes/tortillas.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"No-knead Tortillas"}],["meta",{"name":"twitter:description","content":"Soft, flexible no-knead tortillas made with boiling water for maximum pliability."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/recipes/tortillas.html"}]]},"headers":[],"relativePath":"recipes/tortillas.md","filePath":"recipes/tortillas.md"}'),o={name:"recipes/tortillas.md"};function r(n,e,s,d,h,c){return i(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="no-knead-tortillas" tabindex="-1">No-knead Tortillas <a class="header-anchor" href="#no-knead-tortillas" aria-label="Permalink to “No-knead Tortillas”">​</a></h1><p>No-knead tortillas that are ready in about 90 minutes with minimal prep. Rolling is the only part that needs attention, and this dough stays soft enough to make that manageable. Use the <a href="https://kitchenratio.com/calculator/flatbread/tortillas" target="_blank" rel="noreferrer">KitchenRatio Calculator</a> to scale to any batch.</p><div class="recipe-glance"><div class="recipe-glance-card"><strong>Style</strong><span>Soft, pliable flour tortillas made with hot-water gelatinization.</span></div><div class="recipe-glance-card"><strong>Yield</strong><span>Portion guide targets roughly 10-inch tortillas at about 45-47g each.</span></div><div class="recipe-glance-card"><strong>Best For</strong><span>Burritos, tacos, and fast stovetop flatbreads with minimal hands-on work.</span></div></div><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h2><p>After testing many recipes, I found most tortillas came out too thick or tore during rolling. This version uses boiling water to gelatinize the flour, keeping the dough soft and pliable.</p><p>These tortillas are perfect for burritos, soft tacos, or serving alongside green chili and beans.</p><hr><h2 id="ingredients-example-batch" tabindex="-1">Ingredients (Example Batch) <a class="header-anchor" href="#ingredients-example-batch" aria-label="Permalink to “Ingredients (Example Batch)”">​</a></h2><ul><li><strong>Flour</strong> - 450g</li><li><strong>Water</strong> - 306g boiling water (68% hydration)</li><li><strong>Fat</strong> - 90g (20%)</li><li><strong>Baking soda</strong> - 9g (2%)</li><li><strong>Salt</strong> - ~7g (~1.6%)</li></ul><p>Need a scale? <a href="https://amzn.to/48F9DfT" target="_blank" rel="noreferrer">KitchenAid Digital Scale</a>.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>I prefer lard, but any neutral fat works.</p><ul><li>If using solid fat (lard, butter, shortening), melt it before combining with the hot water to maintain temperature.</li><li>Baking soda is used to increase the water pH and slightly reduce gluten development, which keeps the tortillas soft - it is <strong>not for leavening</strong>.</li></ul></div><hr><h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to “Procedure”">​</a></h2><h3 id="_1-mixing" tabindex="-1">1. Mixing <a class="header-anchor" href="#_1-mixing" aria-label="Permalink to “1. Mixing”">​</a></h3><ul><li>Boil and weigh the water.</li><li>Dissolve salt and baking soda in the hot water.</li><li>Add the fat and stir to combine.</li><li>Gradually add the flour while stirring until fully incorporated. The dough will be very loose.</li><li>Transfer to a container, cover, and let rest at room temperature for 30 minutes.</li></ul><h3 id="_2-divide" tabindex="-1">2. Divide <a class="header-anchor" href="#_2-divide" aria-label="Permalink to “2. Divide”">​</a></h3><ul><li>Weigh the dough, then divide by desired portion size (45-47g yields ~10-inch tortillas).</li><li>Shape each portion into a small ball, tightening the surface against the counter, until the surface is smooth.</li><li>Cover and refrigerate for at least 30 minutes. Roll straight from the fridge.</li></ul><h3 id="_3-roll" tabindex="-1">3. Roll <a class="header-anchor" href="#_3-roll" aria-label="Permalink to “3. Roll”">​</a></h3><ul><li>Preheat a cast iron skillet over medium-high heat.</li><li>Lightly flour the counter and rolling pin.</li><li>Flatten each dough ball by hand after dusting with flour, then roll as thin as possible, rotating and flipping to maintain roundness.</li><li>Keep tortillas from sticking by lightly flouring as needed. Stack carefully without sticking.</li></ul><h3 id="_4-cook" tabindex="-1">4. Cook <a class="header-anchor" href="#_4-cook" aria-label="Permalink to “4. Cook”">​</a></h3><ul><li>Dust excess flour, then place individual tortillas in the cast iron pan and cook.</li><li>Cook about 15-30 seconds per side, flipping twice per side (four flips total). Aim for a light kiss of brown on each side, and do not overcook.</li><li>Remove to a plate and cover with foil or a kitchen towel.</li><li>When all tortillas are finished, flip the entire stack over to prevent the bottom tortilla from getting soggy.</li><li>Leave covered for 10-15 minutes before serving.</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><div class="content-section"><ul><li><a href="/guides/yield-planner.html">Yield Planner</a></li><li><a href="/guides/hydration.html">Hydration</a></li><li><a href="/guides/kitchenratio-calculator.html">KitchenRatio Calculator</a></li></ul></div><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><div class="content-section"><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul></div><blockquote><p><strong>Affiliate Disclaimer</strong><br> This post contains affiliate links. As an Amazon Associate, I earn from qualifying purchases. If you click on a link and make a purchase, I may receive a small commission at no extra cost to you.</p></blockquote>',26)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
